A_T = dict(bg=_L(_b - 5), chrome=_L(_b - 2), ruler=_L(_b + 5), lane0=_L(_b + 1), lane1=_L(_b + 2), laneSel=_L(_b + 6),
           panel='#121216', panel2='#18181d', strip='#24272E', display='#0B0C10', glass='#1C1C24', glassA=.5, line='#25252c',
           grid='255,255,255', gridK=1, ink='#ececf1', lab='#b7b7c2', mut='#8b8b97', dis='#5c5e68', rulerTxt=_L(70),
           accent='#4c8dff', onAccent='#ffffff', sel='#f5c84c', unit='#ffb547', rec='#ff4d4d', over='#ff6b6b', overD='#ff6b6b',
           warn='#f5c84c', ok='#3ecf8e', ph='#3ecf8e', m0='#12804f', m1='#3ecf8e', m2='#f5c84c', m3='#ff3b3b',
           focusIn='#4c8dff', focusOut='#4c8dff', clipA=.36, tip='#2a2a33', tipInk='#ececf1', tipEdge='#6a6c7a')

